33	use crate::desc_helpers::extract_ochids;
34	use crate::jj;
35	use crate::options_flags::squash::{SquashOption, SquashSpec};
36	use crate::status;
37	use crate::subcommand::SubcommandRunner;
38	
39	/// Squash `@` into `@-`, advance BOOKMARK, and push.
40	///
41	/// Captures a repo's trailing working-copy writes into the last
42	/// commit and publishes it: rewriting an already-pushed commit is
43	/// a forced update. Zero-ceremony default: bare `vc-x1 squash-push`
44	/// squashes `@ -> @-` and pushes `main` in `.`.
45	#[derive(Args, Debug)]
46	pub struct SquashPushArgs {
47	    /// Bookmark to advance and push
48	    #[arg(value_name = "BOOKMARK", default_value = "main")]
49	    pub bookmark: String,
50	
51	    /// Path to jj repo
52	    #[arg(short = 'R', long, default_value = ".")]
53	    pub repo: PathBuf,
54	
55	    #[command(flatten)]
56	    pub squash: SquashOption,
57	}
58	
59	/// Per-invocation squash-push inputs: the clap-free shape the op
60	/// works against. Built from `SquashPushArgs` at the binary edge
61	/// via `TryFrom` (fallible only on repo-path canonicalization),
62	/// while `vc-x1 push`'s `squash-push-bot` stage constructs it
63	/// directly.
64	#[derive(Debug)]
65	pub struct SquashPushParams {
66	    pub repo: PathBuf,
67	    pub squash: SquashSpec,
68	    pub bookmark: String,
69	    /// Report an at-rest publish mismatch (BOOKMARK not matching
70	    /// `BOOKMARK@origin`, an earlier publish was lost) before
71	    /// proceeding. True for CLI invocations, which run at rest.
72	    /// `vc-x1 push`'s `squash-push-bot` stage sets false: there
73	    /// the mismatch is the normal mid-push state (`bookmark-set`
74	    /// just moved the bookmark, this stage publishes it), so the
75	    /// report would be a false alarm.
76	    pub report_publish_state: bool,
77	}
78	
79	impl TryFrom<&SquashPushArgs> for SquashPushParams {
80	    type Error = String;
81	
82	    /// Canonicalize `--repo` (early, visible failure on a bad path)
83	    /// and fill the `--squash` default. BOOKMARK maps straight over.
84	    fn try_from(a: &SquashPushArgs) -> Result<Self, String> {
85	        let repo = std::fs::canonicalize(&a.repo)
